import{_ as i,o as a,c as o,a2 as t}from"./chunks/framework.CHeM0PsO.js";const p=JSON.parse('{"title":"Third-party notices","description":"","frontmatter":{},"headers":[],"relativePath":"projects/tuneweave/THIRD_PARTY_NOTICES.md","filePath":"projects/tuneweave/THIRD_PARTY_NOTICES.md"}'),r={name:"projects/tuneweave/THIRD_PARTY_NOTICES.md"};function l(n,e,c,s,d,u){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="third-party-notices" tabindex="-1">Third-party notices <a class="header-anchor" href="#third-party-notices" aria-label="Permalink to &quot;Third-party notices&quot;">​</a></h1><p>TuneWeave is an independent Rust implementation informed by the public protocol research and implementations listed below. Source snapshots are recorded so future ports can be audited precisely.</p><h2 id="neteasecloudmusicapienhanced-api-enhanced" tabindex="-1">NeteaseCloudMusicApiEnhanced/api-enhanced <a class="header-anchor" href="#neteasecloudmusicapienhanced-api-enhanced" aria-label="Permalink to &quot;NeteaseCloudMusicApiEnhanced/api-enhanced&quot;">​</a></h2><ul><li>Source: <a href="https://github.com/NeteaseCloudMusicApiEnhanced/api-enhanced" target="_blank" rel="noreferrer">https://github.com/NeteaseCloudMusicApiEnhanced/api-enhanced</a></li><li>Reviewed commit: <code>8f4873f2e2f677153d398a62d9ca0e3826c3f86d</code></li><li>License: MIT</li><li>Used for: NetEase Cloud Music request protocols, endpoint behavior, response normalization, and authentication flow research.</li></ul><h2 id="mopelotus-lotus-refactor" tabindex="-1">MOPELotus/Lotus-ReFactor <a class="header-anchor" href="#mopelotus-lotus-refactor" aria-label="Permalink to &quot;MOPELotus/Lotus-ReFactor&quot;">​</a></h2><ul><li>Source: <a href="https://github.com/MOPELotus/Lotus-ReFactor" target="_blank" rel="noreferrer">https://github.com/MOPELotus/Lotus-ReFactor</a></li><li>Reviewed commit: <code>8d6ad59ca754a8055711c0b05c0e602442d406fe</code></li><li>License: Lotus-ReFactor Source-Available Proprietary License</li><li>Used for: NetEase Music Partner request logic and implementation details.</li><li>Authorization: MOPELotus states that they contributed 100% of Lotus-ReFactor and explicitly authorizes TuneWeave to reference and reuse its logic and implementation. The public Lotus-ReFactor license is still recorded here accurately for third-party readers.</li></ul><h2 id="l-1124-qqmusicapi" tabindex="-1">L-1124/QQMusicApi <a class="header-anchor" href="#l-1124-qqmusicapi" aria-label="Permalink to &quot;L-1124/QQMusicApi&quot;">​</a></h2><ul><li>Source: <a href="https://github.com/L-1124/QQMusicApi" target="_blank" rel="noreferrer">https://github.com/L-1124/QQMusicApi</a></li><li>Reviewed commit: <code>873255f2774361ac97366bd89a14b8ed9d230aae</code></li><li>License: GNU General Public License v3.0 or later</li><li>Used for: QQ Music CGI request, authentication, catalog, playlist, lyric, media MID, file naming, VKey, and CDN behavior research.</li></ul><p>QQMusicApi remains under GPL-3.0-or-later. TuneWeave does not copy, translate, link, bundle, or redistribute its source code; the Rust implementation is an independent implementation of observed request and response behavior.</p><h2 id="makcre-kugoumusicapi" tabindex="-1">MakcRe/KuGouMusicApi <a class="header-anchor" href="#makcre-kugoumusicapi" aria-label="Permalink to &quot;MakcRe/KuGouMusicApi&quot;">​</a></h2><ul><li>Source: <a href="https://github.com/MakcRe/KuGouMusicApi" target="_blank" rel="noreferrer">https://github.com/MakcRe/KuGouMusicApi</a></li><li>Reviewed commit: <code>62ac8e2f209438d5d480a1dc9dd78b50a52b5748</code></li><li>License: MIT</li><li>Used for: KuGou request signing, device identity, authentication, catalog, lyric, playlist, and media URL behavior research.</li></ul><h2 id="domdkw-migumusic-api-enhanced" tabindex="-1">Domdkw/miguMusic-api-enhanced <a class="header-anchor" href="#domdkw-migumusic-api-enhanced" aria-label="Permalink to &quot;Domdkw/miguMusic-api-enhanced&quot;">​</a></h2><ul><li>Source: <a href="https://github.com/Domdkw/miguMusic-api-enhanced" target="_blank" rel="noreferrer">https://github.com/Domdkw/miguMusic-api-enhanced</a></li><li>Reviewed commit: <code>fbb0121d0c23088c74d63bc95a005c6fada413c1</code></li><li>License: Apache License 2.0</li><li>Used for: Migu catalog, login, PACM token, resource identity, entitlement, and media URL behavior research.</li></ul><h2 id="qyhqiu-kuwomusicapi" tabindex="-1">qyhqiu/kuwoMusicApi <a class="header-anchor" href="#qyhqiu-kuwomusicapi" aria-label="Permalink to &quot;qyhqiu/kuwoMusicApi&quot;">​</a></h2><ul><li>Source: <a href="https://github.com/qyhqiu/kuwoMusicApi" target="_blank" rel="noreferrer">https://github.com/qyhqiu/kuwoMusicApi</a></li><li>Reviewed commit: <code>e8e720b90b4d7e3052078a3380906f2b3349e388</code></li><li>License: Apache License 2.0. The README does not declare an alternative; <code>package.json</code> contains stale ISC metadata and is not treated as overriding the root license.</li><li>Used for: historical Kuwo endpoint inventory, legacy response fields, and project-scope research. Current endpoint usability is determined from the official website and client rather than this snapshot.</li></ul><h2 id="guohuiyuan-music-lib" tabindex="-1">guohuiyuan/music-lib <a class="header-anchor" href="#guohuiyuan-music-lib" aria-label="Permalink to &quot;guohuiyuan/music-lib&quot;">​</a></h2><ul><li>Source: <a href="https://github.com/guohuiyuan/music-lib" target="_blank" rel="noreferrer">https://github.com/guohuiyuan/music-lib</a></li><li>Reviewed commit: <code>b299302e3163765d3efcc9df592700b41867c3d8</code></li><li>License: GNU Affero General Public License v3.0</li><li>Used for: Kuwo lyric, album, playlist, and field-model research, plus Soda Music share, <code>track_v2</code>, lyric, catalog, entitlement, and session research.</li></ul><p>TuneWeave does not copy, translate, link, bundle, or redistribute music-lib source. Its AGPL-3.0 implementation is used only to identify protocol facts that are independently validated against official services and reimplemented under TuneWeave&#39;s architecture.</p><h2 id="unblockneteasemusic-server" tabindex="-1">UnblockNeteaseMusic/server <a class="header-anchor" href="#unblockneteasemusic-server" aria-label="Permalink to &quot;UnblockNeteaseMusic/server&quot;">​</a></h2><ul><li>Source: <a href="https://github.com/UnblockNeteaseMusic/server" target="_blank" rel="noreferrer">https://github.com/UnblockNeteaseMusic/server</a></li><li>Reviewed commit: <code>39e21bfb4b7581f39785b190aeced201d23f0d41</code></li><li>License: GNU Lesser General Public License v3.0 only</li><li>Used for: Kuwo mobile playback, <code>convert_url2</code>, DES protocol, and bounded fallback behavior research. Historical search endpoints are not treated as a current protocol baseline.</li></ul><p>TuneWeave does not link or redistribute this LGPL-3.0-only implementation. The Rust provider independently implements only protocol behavior verified against current official Kuwo services.</p><h2 id="charlespikachu-musicdl" tabindex="-1">CharlesPikachu/musicdl <a class="header-anchor" href="#charlespikachu-musicdl" aria-label="Permalink to &quot;CharlesPikachu/musicdl&quot;">​</a></h2><ul><li>Source: <a href="https://github.com/CharlesPikachu/musicdl" target="_blank" rel="noreferrer">https://github.com/CharlesPikachu/musicdl</a></li><li>Reviewed commit: <code>fddc02586c7b212f1dc705847ead43660d65a91b</code></li><li>License: PolyForm Noncommercial License 1.0.0</li><li>Used for: candidate official Kuwo and Soda Music endpoints, media fields, quality tiers, share-page parsing, and lyric-flow research.</li></ul><p>Only official-service protocol leads are considered. TuneWeave does not copy, translate, bundle, or redistribute musicdl, and never adopts the project&#39;s third-party hosted parser fallbacks.</p><h2 id="listen1-listen1-api" tabindex="-1">listen1/listen1-api <a class="header-anchor" href="#listen1-listen1-api" aria-label="Permalink to &quot;listen1/listen1-api&quot;">​</a></h2><ul><li>Source: <a href="https://github.com/listen1/listen1-api" target="_blank" rel="noreferrer">https://github.com/listen1/listen1-api</a></li><li>Reviewed commit: <code>aa4b9d34aad577a254a70b2754415adcbb17294d</code></li><li>License: MIT</li><li>Used for: historical Kuwo capability inventory, media URL categories, and Listen1 data-model research. The snapshot is not evidence that an endpoint remains usable.</li></ul><h2 id="sakonga-popdownloader" tabindex="-1">SaKongA/PopDownloader <a class="header-anchor" href="#sakonga-popdownloader" aria-label="Permalink to &quot;SaKongA/PopDownloader&quot;">​</a></h2><ul><li>Source: <a href="https://github.com/SaKongA/PopDownloader" target="_blank" rel="noreferrer">https://github.com/SaKongA/PopDownloader</a></li><li>Reviewed commit: <code>8e48fd1d01b7d3d4262149863818ae15ee7e3bc9</code></li><li>License: ISC is declared in <code>package.json</code>; the reviewed snapshot does not contain a root license text.</li><li>Used for: Soda Music login transactions, account data, created and saved playlists, entitlement fields, media download, and local decryption research.</li></ul><p>The snapshot is research-only. TuneWeave does not copy, translate, bundle, or redistribute its source, and independently verifies official platform behavior.</p><h2 id="_520qiuyu-qishuimusicanalysis" tabindex="-1">520Qiuyu/qishuiMusicAnalysis <a class="header-anchor" href="#_520qiuyu-qishuimusicanalysis" aria-label="Permalink to &quot;520Qiuyu/qishuiMusicAnalysis&quot;">​</a></h2><ul><li>Source: <a href="https://github.com/520Qiuyu/qishuiMusicAnalysis" target="_blank" rel="noreferrer">https://github.com/520Qiuyu/qishuiMusicAnalysis</a></li><li>Reviewed commit: <code>b8f4e4f00be7c77ae6d12ca94d849c7f534cd3a9</code></li><li>License: no license file or license declaration was present in the reviewed snapshot.</li><li>Used for: manual research into the Soda Music PC <code>track_v2</code> request shape, device identity, Cookie, <code>x-helios</code>, <code>x-medusa</code>, and response fields.</li></ul><p>Because no license is granted, TuneWeave does not copy, translate, modify, bundle, redistribute, or otherwise reuse this project&#39;s source. It is only an index of protocol questions to validate independently against official traffic.</p><h2 id="baizeyv-sodadownloader" tabindex="-1">baizeyv/SodaDownloader <a class="header-anchor" href="#baizeyv-sodadownloader" aria-label="Permalink to &quot;baizeyv/SodaDownloader&quot;">​</a></h2><ul><li>Source: <a href="https://github.com/baizeyv/SodaDownloader" target="_blank" rel="noreferrer">https://github.com/baizeyv/SodaDownloader</a></li><li>Reviewed commit: <code>893b49c35b7e11ada029e78782092f2553904281</code></li><li>License: MIT</li><li>Used for: Soda Music share links, <code>aid</code> and session behavior, media quality selection, download flow, and encrypted-media interoperability research.</li></ul><h2 id="naiyqaq-qishui-decrypt" tabindex="-1">naiyQAQ/qishui-decrypt <a class="header-anchor" href="#naiyqaq-qishui-decrypt" aria-label="Permalink to &quot;naiyQAQ/qishui-decrypt&quot;">​</a></h2><ul><li>Source: <a href="https://github.com/naiyQAQ/qishui-decrypt" target="_blank" rel="noreferrer">https://github.com/naiyQAQ/qishui-decrypt</a></li><li>Reviewed commit: <code>d360c20a697f9988c6b567c924af5b9784d18390</code></li><li>License: MIT</li><li>Used for: Soda Music <code>spade_a</code> key derivation, MP4 <code>senc</code> parsing, AES-CTR behavior, and FLAC/AAC/MP4 container reconstruction research.</li></ul><p>Any future Rust implementation must independently enforce MP4 box bounds, input/output limits, authorization boundaries, and real-media validation. CENC handling must not be used to bypass membership or purchase restrictions.</p><h2 id="mopelotus-bbdown" tabindex="-1">MOPELotus/BBDown <a class="header-anchor" href="#mopelotus-bbdown" aria-label="Permalink to &quot;MOPELotus/BBDown&quot;">​</a></h2><ul><li>Source: <a href="https://github.com/MOPELotus/BBDown" target="_blank" rel="noreferrer">https://github.com/MOPELotus/BBDown</a></li><li>Reviewed commit: <code>259a5558cee0a349a7ebb60bd31e40c88e5bc1ed</code></li><li>License: MIT</li><li>Used for: Bilibili identifier parsing, metadata, multipart video, DASH audio and video track, authentication, and request header behavior research.</li></ul><h2 id="bilibili-plugins-bilibili-api-collect" tabindex="-1">bilibili-plugins/bilibili-api-collect <a class="header-anchor" href="#bilibili-plugins-bilibili-api-collect" aria-label="Permalink to &quot;bilibili-plugins/bilibili-api-collect&quot;">​</a></h2><ul><li>Source: <a href="https://github.com/bilibili-plugins/bilibili-api-collect" target="_blank" rel="noreferrer">https://github.com/bilibili-plugins/bilibili-api-collect</a></li><li>Reviewed commit: <code>cfc5fddcc8a94b74d91970bb5b4eaeb349addc47</code></li><li>License: Creative Commons Attribution-NonCommercial 4.0 International</li><li>Used for: Bilibili public protocol documentation research, including account, user-space collection/season, favorites-folder, catalog, and write behavior.</li></ul><p>The documentation remains under CC BY-NC 4.0. TuneWeave does not copy, bundle, or redistribute its text or source; the Rust implementation independently implements the documented request and response protocol.</p><h2 id="tuneweave-license-texts" tabindex="-1">TuneWeave license texts <a class="header-anchor" href="#tuneweave-license-texts" aria-label="Permalink to &quot;TuneWeave license texts&quot;">​</a></h2><p>TuneWeave is available under either MIT or Apache-2.0 at the user&#39;s option. The choice is summarized in <code>LICENSE</code>; complete texts are in <code>LICENSE-MIT</code> and <code>LICENSE-APACHE</code>. Required third-party notices are retained under <code>licenses/</code>.</p>',44)])])}const b=i(r,[["render",l]]);export{p as __pageData,b as default};
